pub fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Assumption: tol is strictly positive. If violated, nothing is "close".
    if tol <= 0 {
        return false;
    }

    let diff: i16 = (a as i16) - (b as i16);
    let tol16: i16 = tol as i16;

    diff.abs() < tol16
}

pub fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Assumptions say equal length and non-zero; we enforce equal length defensively.
    assert_eq!(a.len(), b.len(), "input arrays must have equal length");

    let mut result = Vec::with_capacity(a.len());
    for (&ai, &bi) in a.iter().zip(b.iter()) {
        result.push(is_close_i8(ai, bi, tol));
    }
    result
}

