    #[test]
    fn test_is_close_strict() {
        assert_eq!(is_close_i8(10, 12, 3), true);  // diff=2 < 3
        assert_eq!(is_close_i8(10, 13, 3), false); // diff=3 == tol -> false
        assert_eq!(is_close_i8(-5, -7, 2), false); // diff=2 == tol -> false
        assert_eq!(is_close_i8(-5, -6, 2), true);  // diff=1 < 2
    }

    #[test]
    fn test_is_close_extremes_no_overflow() {
        // diff = -128 - 127 = -255, abs=255
        assert_eq!(is_close_i8(i8::MIN, i8::MAX, 127), false);
        assert_eq!(is_close_i8(i8::MIN, i8::MIN, 1), true);
    }

